#!/usr/bin/env python3
"""DG-0012: SEC EDGAR Filing Data

Fetches SEC EDGAR filing data for US public companies.
Uses the free SEC EDGAR REST API (no auth, 10 req/sec).

Usage:
    python3 method_sec_edgar.py AAPL
    python3 method_sec_edgar.py MSFT --filing-type 10-Q --limit 3
"""
import json, sys, time, re, urllib.request, urllib.parse, urllib.error

METHOD_ID = 'DG-0012'
METHOD_NAME = 'SEC EDGAR'
EDGAR_BASE = 'https://data.sec.gov'
COMPANY_TICKERS_URL = f'{EDGAR_BASE}/files/company_tickers.json'
USER_AGENT = 'ClaudeResearch/1.0 (research@example.com)'
TIMEOUT = 15
_LAST_REQUEST_TIME = 0  # Rate limiting

# Cache integration (optional)
USE_CACHE = True
_cached_request = None
try:
    if USE_CACHE:
        from request_cache import cached_request as _cached_request
except ImportError:
    pass

def _api_get(url: str) -> dict|list:
    """SEC EDGAR API GET with User-Agent and rate limiting."""
    global _LAST_REQUEST_TIME
    elapsed = time.time() - _LAST_REQUEST_TIME
    if elapsed < 0.1:  # 10 req/sec limit
        time.sleep(0.1 - elapsed)
    headers = {'User-Agent': USER_AGENT, 'Accept': 'application/json'}
    try:
        if _cached_request is not None:
            raw = _cached_request(url, headers=headers, timeout=TIMEOUT)
            _LAST_REQUEST_TIME = time.time()
            return json.loads(raw.decode('utf-8'))
        req = urllib.request.Request(url, headers=headers)
        with urllib.request.urlopen(req, timeout=TIMEOUT) as resp:
            _LAST_REQUEST_TIME = time.time()
            return json.loads(resp.read().decode('utf-8'))
    except urllib.error.HTTPError as e:
        return {'error': f'HTTP {e.code}: {e.reason}'}
    except (urllib.error.URLError, OSError) as e:
        return {'error': f'Network error: {e}'}

def ticker_to_cik(ticker: str) -> tuple[str, str]:
    """Map ticker to (CIK zero-padded to 10 digits, company_name)."""
    data = _api_get(COMPANY_TICKERS_URL)
    if isinstance(data, dict) and 'error' in data:
        return None, data['error']
    ticker_upper = ticker.upper()
    for entry in data.values():
        if entry.get('ticker', '').upper() == ticker_upper:
            cik = str(entry['cik_str']).zfill(10)
            return cik, entry.get('title', '')
    return None, f'Ticker {ticker} not found'

def get_recent_filings(cik: str, form_type: str = '10-K', limit: int = 5) -> list[dict]:
    """Fetch recent filings from submissions endpoint."""
    url = f'{EDGAR_BASE}/submissions/CIK{cik}.json'
    data = _api_get(url)
    if 'error' in data: return [data]
    recent = data.get('filings', {}).get('recent', {})
    forms = recent.get('form', [])
    dates = recent.get('filingDate', [])
    accessions = recent.get('accessionNumber', [])
    results = []
    for i, f in enumerate(forms):
        if form_type != 'all' and f != form_type: continue
        if len(results) >= limit: break
        acc = accessions[i].replace('-', '')
        results.append({'form_type': f, 'filing_date': dates[i], 'accession_number': accessions[i], 'filing_url': f'https://www.sec.gov/Archives/edgar/data/{cik}/{acc}'})
    return results

def get_company_facts(cik: str) -> dict:
    """Fetch XBRL company facts: Revenue, NetIncome, EPS, Assets, Liabilities."""
    url = f'{EDGAR_BASE}/api/xbrl/companyfacts/CIK{cik}.json'
    data = _api_get(url)
    if 'error' in data: return data
    us_gaap = data.get('facts', {}).get('us-gaap', {})
    def latest_annual(concept):
        units = us_gaap.get(concept, {}).get('units', {})
        for unit_type, vals in units.items():
            annual = [v for v in vals if v.get('form') == '10-K']
            if annual: return annual[-1]
        return None
    return {k: latest_annual(k) for k in ['Revenues','RevenueFromContractWithCustomerExcludingAssessedTax','NetIncomeLoss','EarningsPerShareBasic','Assets','Liabilities','StockholdersEquity']}

def run(query: str, filing_type: str = '10-K', limit: int = 5) -> dict:
    t0 = time.time()
    cik, company = ticker_to_cik(query)
    if cik is None: return {'method_id': METHOD_ID, 'error': company}
    filings = get_recent_filings(cik, filing_type, limit)
    facts = get_company_facts(cik)
    return {'method_id': METHOD_ID, 'method_name': METHOD_NAME, 'query': query, 'results': filings, 'company_facts': facts, 'metadata': {'duration_seconds': round(time.time()-t0,2), 'cik': cik, 'company_name': company, 'ticker': query.upper(), 'sources_count': len(filings), 'data_points': sum(1 for v in facts.values() if v)}}

if __name__ == '__main__':
    q = sys.argv[1] if len(sys.argv) > 1 else 'AAPL'
    ft = sys.argv[2] if len(sys.argv) > 2 else '10-K'
    print(json.dumps(run(q, ft), indent=2, default=str))

#!/usr/bin/env python3
"""DG-0013: FRED Economic Data

Fetches Federal Reserve Economic Data for macro analysis.
Requires FRED_API_KEY environment variable (free at fred.stlouisfed.org).

Usage:
    python3 method_fred.py GDP
    python3 method_fred.py dashboard
    python3 method_fred.py 'unemployment rate' --mode search
"""
import json, sys, time, os, re, urllib.request, urllib.parse, urllib.error

METHOD_ID = 'DG-0013'
METHOD_NAME = 'FRED Economic Data'
FRED_BASE = 'https://api.stlouisfed.org/fred'
TIMEOUT = 15

KEY_SERIES = {
    'GDP': 'Gross Domestic Product',
    'CPIAUCSL': 'Consumer Price Index (All Urban Consumers)',
    'UNRATE': 'Unemployment Rate',
    'DFF': 'Federal Funds Effective Rate',
    'T10Y2Y': '10Y-2Y Treasury Spread (Yield Curve)',
    'M2SL': 'M2 Money Supply',
    'DEXUSEU': 'USD/EUR Exchange Rate',
    'VIXCLS': 'CBOE Volatility Index (VIX)',
    'FEDFUNDS': 'Federal Funds Rate',
    'SP500': 'S&P 500 Index'
}

# BLS fallback series (no API key required)
BLS_FALLBACK = {
    'CES0000000001': 'Total Nonfarm Employment',
    'LNS14000000': 'Unemployment Rate',
    'CUSR0000SA0': 'CPI All Items'
}
BLS_BASE = 'https://api.bls.gov/publicAPI/v2/timeseries/data/'

# Cache integration
USE_CACHE = True
_cached_request = None
try:
    if USE_CACHE:
        from request_cache import cached_request as _cached_request
except ImportError:
    pass

def _fred_get(endpoint: str, params: dict) -> dict:
    """FRED API GET with API key injection."""
    api_key = os.environ.get('FRED_API_KEY', '')
    if not api_key:
        return {'error': 'FRED_API_KEY environment variable not set. Get free key at https://fred.stlouisfed.org/docs/api/api_key.html'}
    params['api_key'] = api_key
    params['file_type'] = 'json'
    qs = urllib.parse.urlencode(params)
    url = f'{FRED_BASE}/{endpoint}?{qs}'
    headers = {'User-Agent': 'ClaudeResearch/1.0'}
    try:
        if _cached_request:
            raw = _cached_request(url, headers=headers, timeout=TIMEOUT)
            return json.loads(raw.decode('utf-8'))
        req = urllib.request.Request(url, headers=headers)
        with urllib.request.urlopen(req, timeout=TIMEOUT) as resp:
            return json.loads(resp.read().decode('utf-8'))
    except urllib.error.HTTPError as e:
        return {'error': f'HTTP {e.code}: {e.reason}'}
    except (urllib.error.URLError, OSError) as e:
        return {'error': f'Network error: {e}'}

def _bls_get(series_ids: list[str], start_year: int, end_year: int) -> dict:
    """BLS API v2 fallback (no API key for basic access)."""
    payload = json.dumps({'seriesid': series_ids, 'startyear': str(start_year), 'endyear': str(end_year)}).encode('utf-8')
    req = urllib.request.Request(BLS_BASE, data=payload, headers={'Content-Type': 'application/json'})
    try:
        with urllib.request.urlopen(req, timeout=TIMEOUT) as resp:
            return json.loads(resp.read().decode('utf-8'))
    except Exception as e:
        return {'error': str(e)}

def get_series(series_id: str, start: str = None, end: str = None, limit: int = 100) -> dict:
    """Fetch observations for a FRED series."""
    params = {'series_id': series_id, 'sort_order': 'desc', 'limit': str(limit)}
    if start: params['observation_start'] = start
    if end: params['observation_end'] = end
    return _fred_get('series/observations', params)

def get_series_info(series_id: str) -> dict:
    """Fetch metadata for a FRED series."""
    return _fred_get('series', {'series_id': series_id})

def search_series(keywords: str, limit: int = 10) -> list[dict]:
    """Search for FRED series by keywords."""
    data = _fred_get('series/search', {'search_text': keywords, 'limit': str(limit)})
    if 'error' in data: return [data]
    return [{'id': s['id'], 'title': s['title'], 'frequency': s.get('frequency_short',''), 'units': s.get('units',''), 'popularity': s.get('popularity',0)} for s in data.get('seriess', [])]

def get_dashboard() -> dict:
    """Fetch latest values for all KEY_SERIES. Returns macro snapshot."""
    dashboard = {}
    for sid, name in KEY_SERIES.items():
        obs = get_series(sid, limit=2)
        if 'error' in obs:
            dashboard[sid] = {'name': name, 'error': obs['error']}
            continue
        observations = obs.get('observations', [])
        if observations:
            latest = observations[0]
            previous = observations[1] if len(observations) > 1 else None
            val = float(latest['value']) if latest['value'] != '.' else None
            prev_val = float(previous['value']) if previous and previous['value'] != '.' else None
            change = round(val - prev_val, 4) if val is not None and prev_val is not None else None
            dashboard[sid] = {'name': name, 'date': latest['date'], 'value': val, 'previous_value': prev_val, 'change': change}
    return dashboard

def run(query: str, mode: str = 'auto', **kwargs) -> dict:
    t0 = time.time()
    if mode == 'dashboard' or query.lower() == 'dashboard':
        dash = get_dashboard()
        return {'method_id': METHOD_ID, 'method_name': METHOD_NAME, 'query': 'dashboard', 'results': dash, 'metadata': {'duration_seconds': round(time.time()-t0,2), 'sources_count': len(dash), 'data_points': sum(1 for v in dash.values() if 'value' in v)}}
    if mode == 'search' or (mode == 'auto' and not re.match(r'^[A-Z0-9]+$', query)):
        results = search_series(query, kwargs.get('limit', 10))
        return {'method_id': METHOD_ID, 'method_name': METHOD_NAME, 'query': query, 'results': results, 'metadata': {'duration_seconds': round(time.time()-t0,2), 'sources_count': len(results)}}
    # Series mode
    obs = get_series(query.upper(), kwargs.get('observation_start'), kwargs.get('observation_end'), kwargs.get('limit', 100))
    info = get_series_info(query.upper())
    return {'method_id': METHOD_ID, 'method_name': METHOD_NAME, 'query': query, 'results': obs.get('observations', []), 'metadata': {'duration_seconds': round(time.time()-t0,2), 'data_points': len(obs.get('observations',[])), 'series_info': info.get('seriess',[{}])[0] if 'seriess' in info else {}}}

if __name__ == '__main__':
    q = sys.argv[1] if len(sys.argv) > 1 else 'dashboard'
    print(json.dumps(run(q), indent=2, default=str))
